// ratelimit_test.go
package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock(start time.Time) *fakeClock { return &fakeClock{t: start} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	fc := newFakeClock(time.Unix(0, 0))
	tests := []struct {
		name    string
		rate    float64
		burst   int
		clock   Clock
		wantErr error
	}{
		{"zero rate", 0, 1, fc, ErrNonPositiveRate},
		{"negative rate", -1, 1, fc, ErrNonPositiveRate},
		{"zero burst", 1, 0, fc, ErrNonPositiveBurst},
		{"negative burst", 1, -5, fc, ErrNonPositiveBurst},
		{"nil clock", 1, 1, nil, ErrNilClock},
		{"valid", 1, 1, fc, nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := New(tc.rate, tc.burst, tc.clock)
			if tc.wantErr == nil {
				if err != nil {
					t.Fatalf("New() error = %v, want nil", err)
				}
				if l == nil {
					t.Fatal("New() = nil, want non-nil")
				}
				return
			}
			if err != tc.wantErr {
				t.Fatalf("New() error = %v, want %v", err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	start := time.Unix(0, 0)
	tests := []struct {
		name  string
		rate  float64
		burst int
		steps []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst exhausted then refill",
			rate: 1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, true},
				{0, 1, false},
				{time.Second, 1, true},
				{0, 1, false},
			},
		},
		{
			name: "multi-token request",
			rate: 1, burst: 3,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 3, true},
				{0, 2, false},
				{2 * time.Second, 2, true},
				{0, 1, false},
			},
		},
		{
			name: "tokens capped at burst",
			rate: 10, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{time.Hour, 3, false},
				{0, 2, true},
			},
		},
		{
			name: "fractional refill",
			rate: 2, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{250 * time.Millisecond, 1, false},
				{250 * time.Millisecond, 1, true},
			},
		},
		{
			name: "zero and negative n",
			rate: 1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 0, true},
				{0, -1, false},
				{0, 1, true},
			},
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			fc := newFakeClock(start)
			l, err := New(tc.rate, tc.burst, fc)
			if err != nil {
				t.Fatalf("New() error = %v", err)
			}
			for i, s := range tc.steps {
				fc.Advance(s.advance)
				if got := l.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowAndTokens(t *testing.T) {
	fc := newFakeClock(start())
	l, err := New(2, 5, fc)
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	if !l.Allow() {
		t.Fatal("Allow() = false, want true")
	}
	if got := l.Tokens(); got != 4 {
		t.Fatalf("Tokens() = %v, want 4", got)
	}
	fc.Advance(time.Second)
	if got := l.Tokens(); got != 4 { // lazy refill: unchanged until AllowN
		t.Fatalf("Tokens() before AllowN = %v, want 4", got)
	}
	if !l.Allow() {
		t.Fatal("Allow() = false, want true")
	}
	if got := l.Tokens(); got != 4 {
		t.Fatalf("Tokens() after refill = %v, want 4", got)
	}
}

func TestConcurrentAccess(t *testing.T) {
	fc := newFakeClock(start())
	l, err := New(1000, 100, fc)
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	var wg sync.WaitGroup
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 10; j++ {
				if l.Allow() {
					mu.Lock()
					allowed++
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	if allowed > 100 {
		t.Fatalf("allowed = %d, want <= 100", allowed)
	}
}

func start() time.Time { return time.Unix(0, 0) }
